extra_css:
.status::before{width:11px;height:11px;box-sizing:border-box;border:2px solid var(--color-ink);background:transparent}
.status--now::before{background:var(--color-ink)}
.status--dev::before{background:linear-gradient(90deg,var(--color-ink) 50%,transparent 50%)}
.status--prep::before{}
.status--later::before{border:2px dotted var(--color-ink)}
/* branch = name + ink cable PATTERN (solid · double · dashed · dotted · dash-dot); colour is reserved for sodium and the one guest colour per event */
[style*="--cable-soirees"]{--pat:linear-gradient(#16163F,#16163F)}
[style*="--cable-reseau"]{--pat:linear-gradient(#16163F 0 2px,transparent 2px 4px,#16163F 4px 6px)}
[style*="--cable-organiser"]{--pat:repeating-linear-gradient(90deg,#16163F 0 16px,transparent 16px 24px)}
[style*="--cable-apprendre"]{--pat:repeating-linear-gradient(90deg,#16163F 0 5px,transparent 5px 11px)}
[style*="--cable-tekpractice"]{--pat:repeating-linear-gradient(90deg,#16163F 0 18px,transparent 18px 24px,#16163F 24px 29px,transparent 29px 35px)}

.door{border-top:none;padding-top:calc(var(--space-5) + 6px);background:var(--pat,linear-gradient(#16163F,#16163F)) top left/100% 6px no-repeat}
.branch-hero .cable{height:6px;width:96px;background:var(--pat,#16163F)}
.board tbody th a{border-bottom:none;padding-bottom:8px;background:var(--pat,linear-gradient(#16163F,#16163F)) bottom left/100% 6px no-repeat}
